// Wygenerowano z grafu. Zmiany w tym pliku nie wrócą do grafu, edytuj go w edytorze grafów.
class Graph {
    static float x = 200;
    static float y = 120;

    static void Update() {
        if (Input.Held(Btn.Left)) {
            x -= 3;
        }
        if (Input.Held(Btn.Right)) {
            x += 3;
        }
        if (Input.Held(Btn.Up)) {
            y -= 3;
        }
        if (Input.Held(Btn.Down)) {
            y += 3;
        }
        if (Input.Touching()) {
            x = Input.TouchX() * 400 / 320;
            y = Input.TouchY();
        }
    }

    static void Draw() {
        Gfx.Clear(Gfx.Rgb(20, 24, 40));
        Gfx.Circle(x, y, 14, Color.Yellow);
    }
}

